{
    SC_LOCK handle = NULL;
    DWORD err;

    TRACE("%p\n", manager);

    if (!manager)
    {
        SetLastError( ERROR_INVALID_HANDLE );
        return NULL;
    }

    __TRY
    {
        err = svcctl_LockServiceDatabase( manager, &handle );
    }
    __EXCEPT(rpc_filter)
    {
        err = map_exception_code( GetExceptionCode() );
    }
    __ENDTRY

    if (!err) return handle;
    SetLastError( err );
    return 0;
}

{
    DWORD err;

    TRACE("%p\n", lock);

    if (!lock)
    {
        SetLastError( ERROR_INVALID_SERVICE_LOCK );
        return FALSE;
    }

    __TRY
    {
        err = svcctl_UnlockServiceDatabase( &lock );
    }
    __EXCEPT(rpc_filter)
    {
        err = GetExceptionCode();

        if (err == ERROR_INVALID_HANDLE)
            err = ERROR_INVALID_SERVICE_LOCK;
        else
            err = map_exception_code( err );
    }
    __ENDTRY

    if (!err) return TRUE;
    SetLastError( err );
    return FALSE;

}

{
    const struct algorithm *alg = get_alg_object( handle );
    const SYMCRYPT_MAC *mac;

    TRACE( "%p, %p, %lu, %p, %lu, %s, %p, %lu, %#lx\n", handle, pwd, pwd_len, salt, salt_len,
           wine_dbgstr_longlong(iterations), key, key_len, flags );

    if (!alg || !(alg->flags & BCRYPT_ALG_HANDLE_HMAC_FLAG)) return STATUS_INVALID_HANDLE;
    if (!iterations) return STATUS_INVALID_PARAMETER;

    if (!(mac = get_mac_from_alg( alg->id ))) return STATUS_NOT_SUPPORTED;

    if (SymCryptPbkdf2( mac, pwd, pwd_len, salt, salt_len, iterations, key, key_len )) return STATUS_INTERNAL_ERROR;
    return STATUS_SUCCESS;
}

{
    struct key *key = get_key_object( handle );

    TRACE( "%p\n", handle );

    if (!key || key->hdr.magic != MAGIC_KEY) return STATUS_INVALID_HANDLE;

    destroy_key( key );
    return STATUS_SUCCESS;
}

{
    struct key *key = get_key_object( handle );

    TRACE( "%p, %#lx\n", key, flags );

    if (!key || key->flags & KEY_FLAG_FINALIZED) return STATUS_INVALID_HANDLE;

    return finalize_key_pair( key );
}

{
    const struct algorithm *alg = get_alg_object( handle );
    struct key *key;
    const struct key *decrypt_key = NULL;
    NTSTATUS status;

    TRACE( "%p, %p, %s, %p, %p, %lu, %p, %lu, %#lx\n", handle, decrypt_key_handle, debugstr_w(type), ret_handle,
           object, object_len, input, input_len, flags );

    if (!alg || !is_symmetric_alg( alg )) return STATUS_INVALID_HANDLE;
    if (!ret_handle || !type || !input) return STATUS_INVALID_PARAMETER;
    if (decrypt_key_handle && !(decrypt_key = get_key_object( decrypt_key_handle ))) return STATUS_INVALID_HANDLE;

    if ((status = import_key( alg, decrypt_key, type, input, input_len, &key ))) return status;
    *ret_handle = key;

    TRACE( "returning handle %p\n", *ret_handle );
    return STATUS_SUCCESS;
}

{
    struct bluetooth_find_device *find = find_handle;

    TRACE( "(%p)\n", find_handle );

    if (!find_handle)
    {
        SetLastError( ERROR_INVALID_HANDLE );
        return FALSE;
    }

    free( find->device_list );
    free( find );
    SetLastError( ERROR_SUCCESS );
    return TRUE;
}

{
    struct bluetooth_find_radio_handle *find;
    HANDLE device_ret;
    DWORD err;

    TRACE( "(%p, %p)\n", params, radio );

    if (!params)
    {
        SetLastError( ERROR_INVALID_PARAMETER );
        return NULL;
    }
    if (params->dwSize != sizeof( *params ))
    {
        SetLastError( ERROR_REVISION_MISMATCH );
        return NULL;
    }
    if (!(find = calloc( 1, sizeof( *find ) )))
    {
        SetLastError( ERROR_OUTOFMEMORY );
        return NULL;
    }

    find->devinfo = SetupDiGetClassDevsW( &GUID_BTHPORT_DEVICE_INTERFACE, NULL, NULL,
                                          DIGCF_PRESENT | DIGCF_DEVICEINTERFACE );
    if (find->devinfo == INVALID_HANDLE_VALUE)
    {
        free( find );
        return NULL;
    }

    if (BluetoothFindNextRadio( find, &device_ret ))
    {
        *radio = device_ret;
        return find;
    }

    err = GetLastError();
    BluetoothFindRadioClose( find );
    SetLastError( err );
    return NULL;
}

{
    BOOL success;

    TRACE( "(%p, %p)\n", find, info );

    /* This method doesn't perform any validation for info, for some reason. */
    if (!find)
    {
        SetLastError( ERROR_INVALID_HANDLE );
        return FALSE;
    }

    success = device_find_next( find, info );
    if (!success)
        SetLastError( ERROR_NO_MORE_ITEMS );
    else
        SetLastError( ERROR_SUCCESS );
    return success;
}

{
    struct bluetooth_find_radio_handle *find = find_handle;

    TRACE( "(%p)\n", find_handle );

    if (!find_handle)
    {
        SetLastError( ERROR_INVALID_HANDLE );
        return FALSE;
    }

    SetupDiDestroyDeviceInfoList( find->devinfo );
    free( find );
    SetLastError( ERROR_SUCCESS );
    return TRUE;
}

{
    TRACE( "(%p)\n", radio );

    if (!radio)
    {
        BLUETOOTH_FIND_RADIO_PARAMS params = {.dwSize = sizeof( params )};
        HBLUETOOTH_RADIO_FIND find = BluetoothFindFirstRadio( &params, &radio );

        if (!find)
            return FALSE;
        for (;;)
        {
            if (BluetoothIsConnectable( radio ))
            {
                CloseHandle( radio );
                BluetoothFindRadioClose( find );
                return TRUE;
            }

            CloseHandle( radio );
            if (!BluetoothFindNextRadio( find, &radio ))
            {
                BluetoothFindRadioClose( find );
                return FALSE;
            }
        }
    }
    else
    {
        BTH_LOCAL_RADIO_INFO radio_info = {0};
        DWORD bytes;
        DWORD ret;

        ret = DeviceIoControl( radio, IOCTL_BTH_GET_LOCAL_INFO, NULL, 0, &radio_info, sizeof( radio_info ), &bytes,
                               NULL );
        if (!ret)
        {
            ERR( "DeviceIoControl failed: %#lx\n", GetLastError() );
            return FALSE;
        }
        return !!(radio_info.flags & LOCAL_RADIO_CONNECTABLE);
    }
}

{
    TRACE( "(%p)\n", radio );

    if (!radio)
    {
        BLUETOOTH_FIND_RADIO_PARAMS params = {.dwSize = sizeof( params )};
        HBLUETOOTH_RADIO_FIND find = BluetoothFindFirstRadio( &params, &radio );

        if (!find)
            return FALSE;
        for (;;)
        {
            if (BluetoothIsDiscoverable( radio ))
            {
                CloseHandle( radio );
                BluetoothFindRadioClose( find );
                return TRUE;
            }

            CloseHandle( radio );
            if (!BluetoothFindNextRadio( find, &radio ))
            {
                BluetoothFindRadioClose( find );
                return FALSE;
            }
        }
    }
    else
    {
        BTH_LOCAL_RADIO_INFO radio_info = {0};
        DWORD bytes;
        DWORD ret;

        ret = DeviceIoControl( radio, IOCTL_BTH_GET_LOCAL_INFO, NULL, 0, &radio_info, sizeof( radio_info ), &bytes,
                               NULL );
        if (!ret)
        {
            ERR( "DeviceIoControl failed: %#lx\n", GetLastError() );
            return FALSE;
        }
        return !!(radio_info.flags & LOCAL_RADIO_DISCOVERABLE);
    }
}

{
    BLUETOOTH_FIND_RADIO_PARAMS find_params = {0};
    HBLUETOOTH_RADIO_FIND radio_find;
    const static BYTE addr_zero[6];
    BOOL success = FALSE;
    HANDLE radio;
    DWORD ret;

    TRACE( "(%s)\n", debugstr_addr( (BYTE *)addr ) );

    if (!memcmp( addr_zero, &addr->rgBytes, sizeof( addr_zero ) ))
        return ERROR_NOT_FOUND;

    find_params.dwSize = sizeof( find_params );
    radio_find = BluetoothFindFirstRadio( &find_params, &radio );
    if (!radio_find)
    {
        ret = GetLastError();
        return ret == ERROR_NO_MORE_ITEMS ? ERROR_NOT_FOUND : ret;
    }

    do {
        DWORD bytes;
        success |= DeviceIoControl( radio, IOCTL_WINEBTH_RADIO_REMOVE_DEVICE, addr, sizeof( *addr ), NULL, 0, &bytes, NULL );
        CloseHandle( radio );
    } while (BluetoothFindNextRadio( radio_find, &radio ));

    BluetoothFindRadioClose( radio_find );
    return success ? ERROR_SUCCESS : ERROR_NOT_FOUND;
}

{
    SDP_ELEMENT_DATA data = {0};
    DWORD result;
    HBLUETOOTH_CONTAINER_ELEMENT cursor = NULL;

    TRACE( "(%p, %ld, %p, %p)\n", stream, stream_size, callback, param );

    if (stream == NULL || callback == NULL) return ERROR_INVALID_PARAMETER;

    result = BluetoothSdpGetElementData( stream, stream_size, &data );
    if (result != ERROR_SUCCESS)
    {
        SetLastError( ERROR_INVALID_DATA );
        return FALSE;
    }

    switch (data.type)
    {
    case SDP_TYPE_SEQUENCE:
    case SDP_TYPE_ALTERNATIVE:
        break;
    default:
        SetLastError( ERROR_INVALID_DATA );
        return FALSE;
    }

    for (;;)
    {
        SDP_ELEMENT_DATA attrid = {0};
        SDP_ELEMENT_DATA attr = {0};
        BYTE *raw_attr_stream;

        result = BluetoothSdpGetContainerElementData( data.data.sequence.value,
                                                      data.data.sequence.length, &cursor, &attrid );
        if (result == ERROR_NO_MORE_ITEMS) return TRUE;
        if (result || !SDP_ELEMENT_IS_ATTRID( &attrid ))
        {
            SetLastError( ERROR_INVALID_DATA );
            return FALSE;
        }

        raw_attr_stream = cursor;
        result = BluetoothSdpGetContainerElementData( data.data.sequence.value,
                                                      data.data.sequence.length, &cursor, &attr );
        if (result != ERROR_SUCCESS)
        {
            SetLastError( ERROR_INVALID_DATA );
            return FALSE;
        }
        if (!callback( attrid.data.uint16, raw_attr_stream, ((BYTE *)cursor - raw_attr_stream),
                       param ))
            return TRUE;
    }
}

{
    struct get_attr_value_data args = {0};

    TRACE( "(%p %lu %u %p)\n", stream, stream_size, attr_id, data );

    if (stream == NULL || data == NULL) return ERROR_INVALID_PARAMETER;

    args.attr_id = attr_id;
    if (!BluetoothSdpEnumAttributes( stream, stream_size, get_attr_value_callback, &args ))
        return ERROR_INVALID_PARAMETER;
    if (!args.attr_stream) return ERROR_FILE_NOT_FOUND;

    return BluetoothSdpGetElementData( args.attr_stream, args.stream_size, data );
}

{
    BYTE *cursor;
    DWORD result;
    SIZE_T read = 0;

    TRACE( "(%p, %lu, %p, %p)\n", stream, stream_size, handle, data );

    if (stream == NULL || stream_size < sizeof( BYTE ) || handle == NULL || data == NULL)
        return ERROR_INVALID_PARAMETER;

    cursor = (BYTE *)(*handle);

    if (cursor == NULL)
    {
        BYTE header, type, size_desc;
        UINT32 elems_size = 0;
        SIZE_T read = 0;

        header = *stream;
        type = data_elem_type( header );
        size_desc = data_elem_size_desc( header );

        if (type != SDP_TYPE_SEQUENCE && type != SDP_TYPE_ALTERNATIVE)
            return ERROR_INVALID_PARAMETER;
        if (!(size_desc >= SDP_SIZE_DESC_NEXT_UINT8 && size_desc <= SDP_SIZE_DESC_NEXT_UINT32))
            return ERROR_INVALID_PARAMETER;

        stream++;
        if (!sdp_elem_read_var_size( stream, stream_size, &read, size_desc, &elems_size ))
            return ERROR_INVALID_PARAMETER;

        stream += read;
        stream_size -= read;
    }
    else
    {
        if (cursor < stream) return ERROR_INVALID_PARAMETER;
        if (cursor == (stream + stream_size)) return ERROR_NO_MORE_ITEMS;

        stream = cursor;
        stream_size = stream_size - (cursor - stream);
    }
    result = sdp_read_element_data( stream, stream_size, data, &read );
    if (result != ERROR_SUCCESS) return result;

    stream += read;
    TRACE( "handle=%p\n", stream );
    *handle = stream;
    return ERROR_SUCCESS;
}

{
    SIZE_T read = 0;

    TRACE( "(%p, %lu, %p)\n", stream, stream_size, data );

    if (stream == NULL || stream_size < sizeof( BYTE ) || data == NULL)
        return ERROR_INVALID_PARAMETER;

    return sdp_read_element_data( stream, stream_size, data, &read );
}

