{
    struct tlsdata *tlsdata;
    struct apartment *apt;
    HRESULT hr;

    TRACE("%p\n", token);

    if (FAILED(hr = com_get_tlsdata(&tlsdata)))
        return hr;

    if (!token)
        return E_POINTER;

    if (!(apt = apartment_get_current_or_mta()))
    {
        ERR("apartment not initialised\n");
        return CO_E_NOTINITIALIZED;
    }

    if (tlsdata->context_token)
    {
        struct thread_context *context = impl_from_IObjContext(tlsdata->context_token);
        if ((apt->multi_threaded && context != mta_context) ||
            (!apt->multi_threaded && context == mta_context))
        {
            context_token_release(tlsdata->context_token);
            tlsdata->context_token = NULL;
        }
    }

    if (!tlsdata->context_token && apt->multi_threaded && mta_context)
    {
        EnterCriticalSection(&context_cs);
        if (mta_context)
        {
            tlsdata->context_token = &mta_context->IObjContext_iface;
            InterlockedIncrement(&mta_context->ref);
        }
        LeaveCriticalSection(&context_cs);
    }

    if (!tlsdata->context_token)
    {
        struct thread_context *context;

        context = calloc(1, sizeof(*context));
        if (!context)
        {
            apartment_release(apt);
            return E_OUTOFMEMORY;
        }

        context->IComThreadingInfo_iface.lpVtbl = &thread_context_info_vtbl;
        context->IContextCallback_iface.lpVtbl = &thread_context_callback_vtbl;
        context->IObjContext_iface.lpVtbl = &thread_object_context_vtbl;
        context->ref = 1;
        context->reported_ref = 0;
        context->oxid = apt->oxid;

        if (apt->multi_threaded)
        {
            EnterCriticalSection(&context_cs);
            if (!mta_context)
                mta_context = context;
            else
            {
                context_token_release(&context->IObjContext_iface);
                context = mta_context;
                InterlockedIncrement(&context->ref);
            }
            LeaveCriticalSection(&context_cs);
        }

        tlsdata->context_token = &context->IObjContext_iface;
    }

    *token = (ULONG_PTR)tlsdata->context_token;
    TRACE("context_token %p\n", tlsdata->context_token);

    apartment_release(apt);
    return S_OK;
}

{
    WCHAR clsidW[CHARS_IN_GUID];
    HKEY hkey = NULL;
    HRESULT hr;
    LONG size;
    CLSID id;

    if (!clsidOld || !clsidNew)
        return E_INVALIDARG;

    if (FAILED(hr = open_key_for_clsid(clsidOld, NULL, KEY_READ | KEY_WRITE, &hkey)))
        return hr;

    if (IsEqualGUID( clsidOld, clsidNew ))
    {
       size = sizeof(clsidW);
       if (!RegQueryValueW(hkey, L"AutoTreatAs", clsidW, &size) && CLSIDFromString(clsidW, &id) == S_OK)
       {
           if (RegSetValueW(hkey, L"TreatAs", REG_SZ, clsidW, sizeof(clsidW)))
           {
               hr = REGDB_E_WRITEREGDB;
               goto done;
           }
       }
       else
       {
           if (RegDeleteKeyW(hkey, L"TreatAs"))
               hr = REGDB_E_WRITEREGDB;
           goto done;
       }
    }
    else
    {
        if (IsEqualGUID(clsidNew, &CLSID_NULL))
        {
           RegDeleteKeyW(hkey, L"TreatAs");
        }
        else
        {
            StringFromGUID2(clsidNew, clsidW, ARRAY_SIZE(clsidW));
            if (RegSetValueW(hkey, L"TreatAs", REG_SZ, clsidW, sizeof(clsidW)) != ERROR_SUCCESS)
            {
                WARN("RegSetValue failed\n");
                hr = REGDB_E_WRITEREGDB;
                goto done;
            }
        }
    }

done:
    if (hkey) RegCloseKey(hkey);
    return hr;
}

{
    TRACE("%s, %s.\n", debugstr_user_flags(flags), debugstr_hstring(*str));

    if (LOWORD(*flags) == MSHCTX_INPROC)
        WindowsDeleteString(*str);
}

{
    TRACE("%s, %lu, %s.\n", debugstr_user_flags(flags), size, debugstr_hstring(*str));

    ALIGN_LENGTH(size, 7);
    if (LOWORD(*flags) == MSHCTX_INPROC)
        size += sizeof(struct hstring_wire_inproc);
    else
        size += offsetof(struct hstring_wire_local, data[WindowsGetStringLen(*str)]);
    return size;
}

{
    TRACE("%p, %p, %p\n", debugstr_user_flags(flags), buf, str);

    if (LOWORD(*flags) == MSHCTX_INPROC)
    {
        const struct hstring_wire_inproc *wire = ALIGNED_POINTER(buf, 7);

        *str = wire->str;
        TRACE("str=%s\n", debugstr_hstring(*str));
        buf = (BYTE *)(wire + 1);
    }
    else
    {
        const struct hstring_wire_local *wire = ALIGNED_POINTER(buf, 7);
        UINT32 len;
        HRESULT hr;

        len = wire->size / sizeof(WCHAR);
        hr = WindowsCreateString(wire->data, len, str);
        if (FAILED(hr))
            RpcRaiseException(RPC_S_OUT_OF_MEMORY);
        buf = (BYTE *)&wire->data[len];
    }

    return buf;
}

{
    struct apartment *apt;
    struct agile_reference *impl;
    HRESULT hr;

    TRACE("(%d, %s, %p, %p).\n", option, debugstr_guid(riid), obj, agile_reference);

    if (option != AGILEREFERENCE_DEFAULT && option != AGILEREFERENCE_DELAYEDMARSHAL)
        return E_INVALIDARG;

    if (!(apt = apartment_get_current_or_mta()))
    {
        ERR("Apartment not initialized\n");
        return CO_E_NOTINITIALIZED;
    }
    rpc_start_remoting(apt);
    apartment_release(apt);

    if (!object_has_interface(obj, riid))
        return E_NOINTERFACE;
    if (object_has_interface(obj, &IID_INoMarshal))
        return CO_E_NOT_SUPPORTED;

    impl = calloc(1, sizeof(*impl));
    if (!impl)
        return E_OUTOFMEMORY;

    impl->IAgileReference_iface.lpVtbl = &agile_ref_vtbl;
    impl->option = option;
    impl->is_agile = object_has_interface(obj, &IID_IAgileObject);
    impl->ref = 1;
    if (FAILED(hr = CoGetContextToken((ULONG_PTR *)&impl->ctx)))
    {
        free( impl );
        return hr;
    }

    if (option == AGILEREFERENCE_DELAYEDMARSHAL || impl->is_agile)
    {
        impl->obj = obj;
        IUnknown_AddRef(impl->obj);
    }
    else if (option == AGILEREFERENCE_DEFAULT)
    {
        if (FAILED(hr = marshal_object_in_agile_reference(impl, riid, obj)))
        {
            free(impl);
            return hr;
        }
    }

    InitializeCriticalSection(&impl->cs);

    *agile_reference = &impl->IAgileReference_iface;
    return S_OK;
}

