    REAL min_x, min_y, max_x, max_y;
    BOOL empty, infinite;
    RECT bounds;
    GpRegion *tmp_region = NULL;
    GpMatrix transform;

    TRACE("(%p, %p, %p)\n", region, graphics, hrgn);

    if (!region || !hrgn)
        return InvalidParameter;

    if (graphics) {
        stat = GdipCloneRegion(region, &tmp_region);
        region = tmp_region;

        if (stat == Ok)
            stat = get_graphics_transform(graphics, WineCoordinateSpaceGdiDevice, CoordinateSpaceWorld, &transform);

        if (stat == Ok)
            stat = GdipTransformRegion(region, &transform);
    }

    if (stat == Ok)
    {
        get_region_bounding_box(&region->node, &min_x, &min_y, &max_x, &max_y, &empty, &infinite);

        if (empty)
        {
            if (infinite)
                *hrgn = NULL;
            else
                *hrgn = CreateRectRgn(0, 0, 0, 0);
        }
        else
        {
            bounds.left = floorf(min_x);
            bounds.top = floorf(min_y);
            bounds.right = ceilf(max_x) + 1;
            bounds.bottom = ceilf(max_y) + 1;
            stat = get_region_hrgn(&region->node, &bounds, hrgn);
        }
    }

    GdipDeleteRegion(tmp_region);

    return stat;
}

{
    GpStatus stat;
    GpMatrix transform;
    BOOL identity;
    GpRegion* tmp_region = NULL;

    TRACE("(%p, %.2f, %.2f, %p, %p)\n", region, x, y, graphics, res);

    if(!region || !res)
        return InvalidParameter;

    if (graphics)
    {
        stat = get_graphics_transform(graphics, WineCoordinateSpaceGdiDevice, CoordinateSpaceWorld, &transform);
        if (stat != Ok)
            return stat;

        stat = GdipIsMatrixIdentity(&transform, &identity);
        if (stat != Ok)
            return stat;
    }
    else
        identity = TRUE;

    if (!identity)
    {
        GpPointF pt = {x, y};

        stat = GdipTransformMatrixPoints(&transform, &pt, 1);
        if (stat != Ok)
            return stat;

        x = pt.X;
        y = pt.Y;

        stat = GdipCloneRegion(region, &tmp_region);
        if (stat != Ok)
            return stat;

        stat = GdipTransformRegion(tmp_region, &transform);
        if (stat != Ok)
        {
            GdipDeleteRegion(tmp_region);
            return stat;
        }

        region = tmp_region;
    }

    x = gdip_round(x);
    y = gdip_round(y);

    return point_in_region(&region->node, x, y, res);
}

{
    GpStatus status;
    HFONT oldfont, gdifont;
    struct measure_string_args args;
    HDC temp_hdc=NULL, hdc;
    RectF scaled_rect;
    REAL margin_x;
    INT lines, glyphs;
    BOOL vertical = format != NULL ? !!(format->attr & StringFormatFlagsDirectionVertical) : FALSE;

    TRACE("(%p, %s, %i, %p, %s, %p, %p, %p, %p)\n", graphics,
        debugstr_wn(string, length), length, font, debugstr_rectf(rect), format,
        bounds, codepointsfitted, linesfilled);

    if(!graphics || !string || !font || !rect || !bounds)
        return InvalidParameter;

    if(!has_gdi_dc(graphics))
    {
        hdc = temp_hdc = CreateCompatibleDC(0);
        if (!temp_hdc) return OutOfMemory;
    }
    else
    {
        status = gdi_dc_acquire(graphics, &hdc);
        if (status != Ok)
            return status;
    }

    if(linesfilled) *linesfilled = 0;
    if(codepointsfitted) *codepointsfitted = 0;

    if(format)
        TRACE("may be ignoring some format flags: attr %x\n", format->attr);

    transform_properties(graphics, NULL, TRUE, &args.rel_width, &args.rel_height, NULL);
    margin_x = (format && format->generic_typographic) ? 0.0 : font->emSize / 6.0;
    margin_x *= units_scale(font->unit, graphics->unit, vertical ? graphics->yres : graphics->xres, graphics->printer_display);

    scaled_rect.Width = rect->Width * args.rel_width;
    scaled_rect.Height = rect->Height * args.rel_height;
    if (vertical)
    {
        scaled_rect.X = rect->X * args.rel_width;
        scaled_rect.Y = (rect->Y + margin_x) * args.rel_height;
        if (scaled_rect.Height >= 0.5)
        {
            scaled_rect.Height -= margin_x * 2.0 * args.rel_height;
            if (scaled_rect.Height < 0.5) /* doesn't fit */
                goto end;
        }
    }
    else
    {
        scaled_rect.X = (rect->X + margin_x) * args.rel_width;
        scaled_rect.Y = rect->Y * args.rel_height;
        if (scaled_rect.Width >= 0.5)
        {
            scaled_rect.Width -= margin_x * 2.0 * args.rel_width;
            if (scaled_rect.Width < 0.5) /* doesn't fit */
                goto end;
        }
    }

    if (scaled_rect.Width >= 1 << 23) scaled_rect.Width = 1 << 23;
    if (scaled_rect.Height >= 1 << 23) scaled_rect.Height = 1 << 23;

    get_font_hfont(graphics, font, vertical, format, &gdifont, NULL, NULL);
    oldfont = SelectObject(hdc, gdifont);

    set_rect(bounds, rect->X, rect->Y, 0.0f, 0.0f);

    args.bounds = bounds;
    args.codepointsfitted = &glyphs;
    args.linesfilled = &lines;
    args.vertical = vertical;
    lines = glyphs = 0;

    gdi_transform_acquire(graphics);

    gdip_format_string(graphics, hdc, string, length, font, &scaled_rect, format, TRUE,
        measure_string_callback, &args);

    gdi_transform_release(graphics);

    if (linesfilled) *linesfilled = lines;
    if (codepointsfitted) *codepointsfitted = glyphs;

    if (lines)
    {
        if (vertical)
            bounds->Height += margin_x * 2.0;
        else
            bounds->Width += margin_x * 2.0;
    }

    if (lines && format)
    {
        if (vertical)
        {
            switch (format->align)
            {
            case StringAlignmentCenter:
                bounds->Y = rect->Y + (rect->Height - bounds->Height) / 2.0f;
                break;
            case StringAlignmentFar:
                bounds->Y = rect->Y + rect->Height - bounds->Height;
                break;
            default:
                break;
            }

            switch (format->line_align)
            {
            case StringAlignmentCenter:
                bounds->X = rect->X + (rect->Width - bounds->Width) / 2.0f;
                break;
            case StringAlignmentFar:
                bounds->X = rect->X + rect->Width - bounds->Width;
                break;
            default:
                break;
            }
        }
        else
        {
            switch (format->align)
            {
            case StringAlignmentCenter:
                bounds->X = rect->X + (rect->Width - bounds->Width) / 2.0f;
                break;
            case StringAlignmentFar:
                bounds->X = rect->X + rect->Width - bounds->Width;
                break;
            default:
                break;
            }

            switch (format->line_align)
            {
            case StringAlignmentCenter:
                bounds->Y = rect->Y + (rect->Height - bounds->Height) / 2.0f;
                break;
            case StringAlignmentFar:
                bounds->Y = rect->Y + rect->Height - bounds->Height;
                break;
            default:
                break;
            }
        }
    }

    SelectObject(hdc, oldfont);
    DeleteObject(gdifont);
end:
    if (temp_hdc)
        DeleteDC(temp_hdc);
    else
        gdi_dc_release(graphics, hdc);

    return Ok;
}

