    if (RtlIsGenericTableEmpty(table))
        return NULL;

    if (!*previous)
    {
        /* Find the smallest element */
        child = table->TableRoot;
        while (RtlLeftChild(child))
            child = RtlLeftChild(child);
    }
    else
    {
        /* Find the successor of the previous element */
        child = RtlRealSuccessor(*previous);
