    int s = u.i>>63;
    double_t y, z;
    float_t f;
    int even;

    if (e >= 52)
        return x;

    even = e <= -1 ? 1 : !((u.i >> (52 - e)) % 2);

    if (s)
    {
        y = ceil(x);
        z = x - y;
        if (z < -0.5) f = -0.75;
        else if (z == -0.5) f = -0.5;
        else if (z != 0.0) f = -0.25;
        else f = 0.0;

        f = (even ? -0.0 : -1.0) + f;
        f = fp_barrierf(f - tointf) + tointf;
        if (f == (even ? 0.0 : -1.0)) z = y;
        else z = floor(x);
    }
    else
    {
        y = floor(x);
        z = x - y;
        if (z > 0.5) f = 0.75;
        else if (z == 0.5) f = 0.5;
        else if (z != 0.0) f = 0.25;
        else f = 0.0;

        f = (even ? 0.0 : 1.0) + f;
        f = fp_barrierf(f + tointf) - tointf;
        if (f == (even ? 0.0 : 1.0)) z = y;
        else z = ceil(x);
    }

    return z;
#endif
}

